"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * CHANGELOG TRACE: what shipped, routed like a circuit
 *
 *   read      the line is a trace: straight through each
 *             release, stepped aside in between. A bead runs
 *             down it as you scroll, a beat behind the page,
 *             following every bend, and fills each dot it reaches
 *   arrive    entries rise out of a light blur the first time
 *             they come into view
 *   filter    All, New, Improved, Fixed: the pill is thrown to
 *             the choice, entries that don't match fold away,
 *             the trace re-routes as they close and the count
 *             rolls
 *   older     "Show 3 older" folds the rest open and morphs to
 *             "Show fewer"
 *
 * Every entry has an anchor, so a release can be linked to.
 * ───────────────────────────────────────────────────────── */

export interface ChangelogEntry {
  id: string;
  date: string | Date;
  title: string;
  version?: string;
  /** e.g. ["new"], ["improved", "fixed"]. */
  tags?: string[];
  body?: React.ReactNode;
  /** An image or video under the text. */
  media?: React.ReactNode;
}

export interface ChangelogTraceProps extends React.HTMLAttributes<HTMLDivElement> {
  entries: ChangelogEntry[];
  /** How many show before "Show older". */
  initialCount?: number;
  /** Filter chips, by tag; defaults to the tags in the entries. */
  filters?: { tag: string; label: string }[];
  locales?: string | string[];
}

type Point = { x: number; y: number };
type Route = { xs: number[]; ys: number[]; ls: number[]; total: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const THROW = "cubic-bezier(0.34,1.36,0.64,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const TAG_LABEL: Record<string, string> = {
  new: "New",
  improved: "Improved",
  fixed: "Fixed",
};
const TAG_TONE: Record<string, string> = {
  new: "bg-primary/10 text-primary",
  improved: "bg-muted text-foreground/80",
  fixed: "bg-muted text-muted-foreground",
};
const STEP = 14; // how far the trace steps aside between releases
const CLEAR = 24; // straight run either side of a dot
const CORNER = 8; // how much of each bend is rounded
const LAG = 120; // how far the bead trails the page, in ms

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** The bends: straight through each stop, stepped aside between. A step shrinks with its gap, so a release folding away flattens it smoothly. */
function corners(x: number, stops: number[]): Point[] {
  const points: Point[] = [{ x, y: stops[0] }];
  for (let i = 0; i < stops.length - 1; i++) {
    const a = stops[i];
    const b = stops[i + 1];
    const step = Math.min(STEP, Math.max(0, (b - a - 2 * CLEAR) / 3));
    if (step < 0.5) continue;
    points.push(
      { x, y: a + CLEAR },
      { x: x - step, y: a + CLEAR + step },
      { x: x - step, y: b - CLEAR - step },
      { x, y: b - CLEAR },
    );
  }
  points.push({ x, y: stops[stops.length - 1] });
  return points;
}

/** Rounds every bend into the path, and samples it so the bead can find any height along it without asking the DOM. */
function trace(points: Point[]): { d: string; route: Route } {
  const r = (n: number) => Math.round(n * 100) / 100;
  const xs = [points[0].x];
  const ys = [points[0].y];
  const ls = [0];
  const add = (x: number, y: number) => {
    const i = xs.length - 1;
    ls.push(ls[i] + Math.hypot(x - xs[i], y - ys[i]));
    xs.push(x);
    ys.push(y);
  };
  let d = `M${r(points[0].x)} ${r(points[0].y)}`;
  for (let i = 1; i < points.length - 1; i++) {
    const [prev, p, next] = [points[i - 1], points[i], points[i + 1]];
    const d1 = Math.hypot(p.x - prev.x, p.y - prev.y);
    const d2 = Math.hypot(next.x - p.x, next.y - p.y);
    const k = Math.min(CORNER, d1 / 2, d2 / 2);
    if (!(k > 0)) continue;
    const a = {
      x: p.x + ((prev.x - p.x) * k) / d1,
      y: p.y + ((prev.y - p.y) * k) / d1,
    };
    const b = {
      x: p.x + ((next.x - p.x) * k) / d2,
      y: p.y + ((next.y - p.y) * k) / d2,
    };
    d += `L${r(a.x)} ${r(a.y)}Q${r(p.x)} ${r(p.y)} ${r(b.x)} ${r(b.y)}`;
    add(a.x, a.y);
    for (let s = 1; s <= 6; s++) {
      const t = s / 6;
      const u = 1 - t;
      add(
        u * u * a.x + 2 * u * t * p.x + t * t * b.x,
        u * u * a.y + 2 * u * t * p.y + t * t * b.y,
      );
    }
  }
  const last = points[points.length - 1];
  d += `L${r(last.x)} ${r(last.y)}`;
  add(last.x, last.y);
  return { d, route: { xs, ys, ls, total: ls[ls.length - 1] } };
}

/** Where the trace is at height y, and how far along it that is. The trace only ever runs downward. */
function at(route: Route, y: number) {
  const { xs, ys, ls } = route;
  const n = ys.length - 1;
  if (y <= ys[0]) return { x: xs[0], l: 0 };
  if (y >= ys[n]) return { x: xs[n], l: ls[n] };
  let lo = 0;
  let hi = n;
  while (hi - lo > 1) {
    const mid = (lo + hi) >> 1;
    if (ys[mid] < y) lo = mid;
    else hi = mid;
  }
  const t = ys[hi] === ys[lo] ? 0 : (y - ys[lo]) / (ys[hi] - ys[lo]);
  return {
    x: xs[lo] + (xs[hi] - xs[lo]) * t,
    l: ls[lo] + (ls[hi] - ls[lo]) * t,
  };
}

/** Position inside `root` from layout boxes, so transforms (an entry still arriving) don't throw it off. */
function offsetIn(el: HTMLElement, root: HTMLElement) {
  let x = el.offsetWidth / 2;
  let y = el.offsetHeight / 2;
  let node: HTMLElement | null = el;
  while (node && node !== root) {
    x += node.offsetLeft;
    y += node.offsetTop;
    node = node.offsetParent as HTMLElement | null;
  }
  return { x, y };
}

/** Rises out of a light blur the first time it scrolls into view. */
function Arrive({
  reduced,
  children,
}: {
  reduced: boolean;
  children: React.ReactNode;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  const [seen, setSeen] = React.useState(reduced);
  React.useEffect(() => {
    if (seen) return;
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setSeen(true);
          observer.disconnect();
        }
      },
      { rootMargin: "0px 0px -12% 0px" },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [seen]);
  return (
    <div
      ref={ref}
      style={{
        opacity: seen ? 1 : 0,
        transform: seen ? "none" : "translateY(14px)",
        filter: seen ? "none" : "blur(4px)",
        transition: reduced
          ? "none"
          : `opacity 560ms ${EASE}, transform 700ms ${EASE}, filter 560ms ${EASE}`,
      }}
    >
      {children}
    </div>
  );
}

export function ChangelogTrace({
  entries,
  initialCount = 4,
  filters: filtersProp,
  locales,
  className = "",
  ...props
}: ChangelogTraceProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [filter, setFilter] = React.useState<string | null>(null);
  const [showAll, setShowAll] = React.useState(false);
  const [lit, setLit] = React.useState<Set<string>>(() => new Set());
  const listRef = React.useRef<HTMLOListElement>(null);
  const baseRef = React.useRef<SVGPathElement>(null);
  const fillRef = React.useRef<SVGPathElement>(null);
  const beadRef = React.useRef<SVGCircleElement>(null);
  const dotRefs = React.useRef(new Map<string, HTMLSpanElement>());
  const reducedRef = React.useRef(reduced);
  const chipRefs = React.useRef<(HTMLButtonElement | null)[]>([]);
  const [pill, setPill] = React.useState({ left: 0, width: 0, ready: false });

  const filters = React.useMemo(() => {
    if (filtersProp) return filtersProp;
    const tags = Array.from(new Set(entries.flatMap((e) => e.tags ?? [])));
    return tags.map((tag) => ({
      tag,
      label: TAG_LABEL[tag] ?? tag.charAt(0).toUpperCase() + tag.slice(1),
    }));
  }, [entries, filtersProp]);
  const chips = [{ tag: null as string | null, label: "All" }, ...filters];

  const matches = entries.filter((e) => !filter || e.tags?.includes(filter));
  const limit = showAll ? Infinity : initialCount;
  const shownIds = new Set(matches.slice(0, limit).map((e) => e.id));
  const hiddenOlder = Math.max(0, matches.length - initialCount);
  const idsKey = entries.map((e) => e.id).join("\n");

  React.useEffect(() => {
    reducedRef.current = reduced;
  }, [reduced]);

  // The trace is laid out from where the dots sit, and drawn as far as the reader has got. Every frame writes straight to the SVG;
  // React only hears about it when a dot lights.
  React.useEffect(() => {
    const list = listRef.current;
    const base = baseRef.current;
    const fill = fillRef.current;
    const bead = beadRef.current;
    if (!list || !base || !fill || !bead) return;
    let route: Route | null = null;
    let dots: { id: string; y: number }[] = [];
    let drawn = NaN;
    let frame = 0;
    let last = 0;
    let visible = false;
    let litKey = "";

    const paint = () => {
      if (!route) return;
      const top = route.ys[0];
      const end = route.ys[route.ys.length - 1];
      const y = Math.min(end, Math.max(top, drawn));
      const { x, l } = at(route, y);
      fill.style.strokeDashoffset = String(route.total - l);
      bead.style.transform = `translate(${x}px, ${y}px)`;
      bead.style.opacity = y > top + 1 && y < end - 1 ? "1" : "0";
      const now = dots.filter((d) => d.y <= y + 0.5).map((d) => d.id);
      const key = now.join(" ");
      if (key !== litKey) {
        litKey = key;
        setLit(new Set(now));
      }
    };

    // One frame: aim at 55% down the screen, close part of the gap (all of it with reduced motion), draw.
    const tick = (now: number) => {
      frame = 0;
      if (!route) return;
      const top = route.ys[0];
      const end = route.ys[route.ys.length - 1];
      const target = Math.min(
        end,
        Math.max(
          top,
          window.innerHeight * 0.55 - list.getBoundingClientRect().top,
        ),
      );
      const dt = last ? Math.min(64, now - last) : 16;
      last = now;
      if (Number.isNaN(drawn)) drawn = top;
      drawn +=
        (target - drawn) * (reducedRef.current ? 1 : 1 - Math.exp(-dt / LAG));
      if (Math.abs(target - drawn) < 0.25) drawn = target;
      paint();
      if (drawn !== target) frame = requestAnimationFrame(tick);
      else last = 0;
    };
    const run = () => {
      if (visible && !frame) frame = requestAnimationFrame(tick);
    };

    const ids = idsKey.split("\n");
    const layout = () => {
      // Folded releases at the end sit just below the list; hold them to its last line.
      const end = list.offsetHeight - 8;
      const found = ids.flatMap((key) => {
        const el = dotRefs.current.get(key);
        if (!el) return [];
        const { x, y } = offsetIn(el, list);
        return [{ id: key, x, y: Math.min(y, end) }];
      });
      if (!found.length) return;
      dots = found.map(({ id, y }) => ({ id, y }));
      const { d, route: next } = trace(
        corners(found[0].x, [
          ...dots.map((dot) => dot.y),
          Math.max(end, dots[dots.length - 1].y),
        ]),
      );
      route = next;
      base.setAttribute("d", d);
      fill.setAttribute("d", d);
      fill.setAttribute("pathLength", String(next.total));
      fill.style.strokeDasharray = `${next.total} ${next.total}`;
      if (Number.isNaN(drawn)) fill.style.strokeDashoffset = String(next.total);
      else paint();
      run();
    };

    // Folding entries resize the list every frame they move, so the trace re-routes with them.
    const resize = new ResizeObserver(layout);
    resize.observe(list);
    list.querySelectorAll(":scope > li").forEach((li) => resize.observe(li));
    // Only listen while the timeline is on screen.
    const seen = new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting;
      run();
    });
    seen.observe(list);
    window.addEventListener("scroll", run, { passive: true, capture: true });
    window.addEventListener("resize", run);
    return () => {
      resize.disconnect();
      seen.disconnect();
      window.removeEventListener("scroll", run, { capture: true });
      window.removeEventListener("resize", run);
      cancelAnimationFrame(frame);
    };
  }, [idsKey]);

  React.useLayoutEffect(() => {
    const el = chipRefs.current[chips.findIndex((c) => c.tag === filter)];
    if (!el) return;
    setPill((p) =>
      p.left === el.offsetLeft && p.width === el.offsetWidth
        ? p
        : { left: el.offsetLeft, width: el.offsetWidth, ready: p.width > 0 },
    );
  }, [filter, filters.length]);

  const dateText = (d: string | Date) =>
    new Date(d).toLocaleDateString(locales ?? "en-GB", {
      day: "numeric",
      month: "short",
      year: "numeric",
    });
  const fold = (open: boolean): React.CSSProperties => ({
    gridTemplateRows: open ? "1fr" : "0fr",
    opacity: open ? 1 : 0,
    transition: reduced
      ? "none"
      : `grid-template-rows 480ms ${EASE}, opacity ${open ? "380ms" : "160ms"} ${EASE}`,
  });

  return (
    // Laid out by its own width, not the screen's, so it reads right in a narrow column too.
    <div className="w-full">
      {/* Its natural width where the parent sizes to its content, without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 720px)" }}
      />
      <div className="@container w-full">
        <div className={`w-full ${className}`} {...props}>
          <div className="mb-8 flex flex-wrap items-center justify-between gap-3">
            <div
              role="radiogroup"
              aria-label="Show"
              className="relative inline-flex rounded-full bg-muted p-0.5"
            >
              <span
                aria-hidden="true"
                className="absolute inset-y-0.5 left-0 rounded-full bg-background shadow-[0_0_0_1px_var(--border)]"
                style={{
                  width: pill.width,
                  transform: `translateX(${pill.left}px)`,
                  transition:
                    pill.ready && !reduced
                      ? `transform 460ms ${THROW}, width 380ms ${EASE}`
                      : "none",
                }}
              />
              {chips.map((c, i) => {
                const selected = c.tag === filter;
                return (
                  <button
                    key={c.label}
                    ref={(el) => {
                      chipRefs.current[i] = el;
                    }}
                    type="button"
                    role="radio"
                    aria-checked={selected}
                    tabIndex={selected ? 0 : -1}
                    onClick={() => setFilter(c.tag)}
                    onKeyDown={(e) => {
                      if (e.key !== "ArrowRight" && e.key !== "ArrowLeft")
                        return;
                      e.preventDefault();
                      const next =
                        (i + (e.key === "ArrowRight" ? 1 : -1) + chips.length) %
                        chips.length;
                      setFilter(chips[next].tag);
                      chipRefs.current[next]?.focus();
                    }}
                    className={`cursor-pointer relative h-8 rounded-full px-3.5 text-[12.5px] font-medium transition-colors duration-300 ${FOCUS} ${selected ? "text-foreground" : "text-muted-foreground hover:text-foreground"}`}
                  >
                    {c.label}
                  </button>
                );
              })}
            </div>
            <p className="flex items-baseline gap-[0.3em] text-[12.5px] tabular-nums text-muted-foreground">
              <NumberRoll value={matches.length} duration={600} />
              <TextMorph>
                {matches.length === 1 ? "update" : "updates"}
              </TextMorph>
            </p>
          </div>

          <div className="relative">
            {/* The trace, the part of it you've read, and the bead at its tip. */}
            <svg
              aria-hidden="true"
              className="pointer-events-none absolute inset-0 h-full w-full overflow-visible"
            >
              <path
                ref={baseRef}
                fill="none"
                strokeWidth={1}
                className="stroke-border"
              />
              <path
                ref={fillRef}
                fill="none"
                strokeWidth={1}
                strokeLinecap="round"
                className="stroke-foreground/70"
              />
              <circle
                ref={beadRef}
                r={2.5}
                className="fill-foreground"
                style={{
                  opacity: 0,
                  transition: reduced ? "none" : "opacity 200ms",
                }}
              />
            </svg>

            <ol ref={listRef} className="relative">
              {entries.map((e) => {
                const shown = shownIds.has(e.id);
                const on = lit.has(e.id);
                return (
                  <li
                    key={e.id}
                    id={e.id}
                    inert={!shown}
                    aria-hidden={!shown || undefined}
                    className="grid scroll-mt-24"
                    style={fold(shown)}
                  >
                    <div className="min-h-0 overflow-hidden">
                      <Arrive reduced={reduced}>
                        <article className="grid grid-cols-[11px_1fr] gap-x-5 pb-12 pl-4 @[36rem]:grid-cols-[104px_11px_1fr] @[36rem]:gap-x-6 @[36rem]:pl-0">
                          <div className="hidden pt-0.5 text-right @[36rem]:block">
                            <time
                              dateTime={new Date(e.date).toISOString()}
                              className="text-[12.5px] text-muted-foreground"
                            >
                              {dateText(e.date)}
                            </time>
                            {e.version && (
                              <p className="mt-1 font-mono text-[11.5px] text-muted-foreground/80">
                                {e.version}
                              </p>
                            )}
                          </div>
                          {/* The dot fills when the bead reaches it. */}
                          <span
                            ref={(el) => {
                              if (el) dotRefs.current.set(e.id, el);
                              else dotRefs.current.delete(e.id);
                            }}
                            aria-hidden="true"
                            className="relative mt-[5px] flex size-[11px] items-center justify-center rounded-full bg-background shadow-[inset_0_0_0_1px_var(--border)] transition-[box-shadow] duration-500"
                            style={{
                              boxShadow: on
                                ? "inset 0 0 0 1px color-mix(in oklab, var(--foreground) 70%, transparent)"
                                : undefined,
                            }}
                          >
                            <span
                              className="size-[5px] rounded-full bg-foreground/70"
                              style={{
                                transform: on ? "scale(1)" : "scale(0)",
                                transition: reduced
                                  ? "none"
                                  : `transform 420ms ${THROW}`,
                              }}
                            />
                          </span>
                          <div className="min-w-0">
                            <div className="mb-2 flex flex-wrap items-center gap-2 @[36rem]:hidden">
                              <time
                                dateTime={new Date(e.date).toISOString()}
                                className="text-[12px] text-muted-foreground"
                              >
                                {dateText(e.date)}
                              </time>
                              {e.version && (
                                <span className="font-mono text-[11px] text-muted-foreground/80">
                                  {e.version}
                                </span>
                              )}
                            </div>
                            {e.tags && e.tags.length > 0 && (
                              <div className="mb-2 flex flex-wrap gap-1.5">
                                {e.tags.map((t) => (
                                  <span
                                    key={t}
                                    className={`rounded-full px-2 py-px text-[11px] font-medium ${TAG_TONE[t] ?? "bg-muted text-foreground/80"}`}
                                  >
                                    {TAG_LABEL[t] ?? t}
                                  </span>
                                ))}
                              </div>
                            )}
                            <h3 className="text-[17px] font-medium leading-snug tracking-[-0.015em] text-foreground">
                              <a
                                href={`#${e.id}`}
                                className={`rounded hover:underline hover:decoration-border hover:underline-offset-4 ${FOCUS}`}
                              >
                                {e.title}
                              </a>
                            </h3>
                            {e.body && (
                              <div className="mt-2 text-[14px] leading-relaxed text-muted-foreground [&_li]:mt-1 [&_ul]:mt-2 [&_ul]:list-disc [&_ul]:pl-5">
                                {e.body}
                              </div>
                            )}
                            {e.media && (
                              <div className="mt-4 overflow-hidden rounded-[16px] border border-border">
                                {e.media}
                              </div>
                            )}
                          </div>
                        </article>
                      </Arrive>
                    </div>
                  </li>
                );
              })}
            </ol>

            {hiddenOlder > 0 && (
              <div className="pl-[47px] @[36rem]:pl-[163px]">
                <button
                  type="button"
                  aria-expanded={showAll}
                  onClick={() => setShowAll((s) => !s)}
                  className={`cursor-pointer inline-flex h-9 items-center rounded-full px-4 text-[13px] font-medium text-foreground shadow-[inset_0_0_0_1px_var(--border)] transition-colors hover:bg-accent ${FOCUS}`}
                >
                  <TextMorph>
                    {showAll ? "Show fewer" : `Show ${hiddenOlder} older`}
                  </TextMorph>
                </button>
              </div>
            )}
          </div>
          <p id={`${id}-status`} role="status" className="sr-only">
            {`${matches.length} ${matches.length === 1 ? "update" : "updates"}`}
          </p>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

